import React from 'react';
import {
  ResponsiveContainer,
  LineChart,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
  Brush,
  ReferenceLine
} from 'recharts';

// Fungsi helper untuk memformat tanggal
const formatDate = (dateString) => {
  const date = new Date(dateString);
  // Cek apakah tanggal valid
  if (isNaN(date.getTime())) return dateString;

  return date.toLocaleDateString('id-ID', {
    day: '2-digit',
    month: '2-digit',
    year: 'numeric'
  });
};

// Fungsi helper untuk memformat angka sebagai mata uang
const formatCurrency = (value, currencySymbol = 'Rp') => {
  if (typeof value !== 'number') return '-';
  return `${currencySymbol} ${value.toLocaleString('id-ID')}`;
};

// Custom Tooltip komponen
const CustomTooltip = ({ active, payload, label, currencySymbol }) => {
  if (active && payload && payload.length) {
    const data = payload[0].payload;
    
    // Hitung perubahan harga dari titik sebelumnya jika tersedia
    const priceChange = data.previousClose ? data.Close - data.previousClose : 0;
    const percentChange = data.previousClose ? (priceChange / data.previousClose) * 100 : 0;
    const isPositive = priceChange >= 0;

    return (
      <div className="custom-tooltip" style={{ 
        backgroundColor: 'white',
        padding: '10px',
        border: '1px solid #ddd',
        borderRadius: '5px',
        boxShadow: '0 2px 5px rgba(0,0,0,0.15)'
      }}>
        <p style={{ fontWeight: 'bold', marginBottom: '5px', borderBottom: '1px solid #eee', paddingBottom: '5px' }}>
          {formatDate(data.Date || data.Datetime)}
        </p>
        <div style={{ fontSize: '14px' }}>
          <p style={{ margin: '3px 0', display: 'flex', justifyContent: 'space-between' }}>
            <span style={{ marginRight: '15px', color: '#666' }}>Buka:</span>
            <span style={{ fontWeight: '500' }}>{formatCurrency(data.Open, currencySymbol)}</span>
          </p>
          <p style={{ margin: '3px 0', display: 'flex', justifyContent: 'space-between' }}>
            <span style={{ marginRight: '15px', color: '#666' }}>Tertinggi:</span>
            <span style={{ fontWeight: '500' }}>{formatCurrency(data.High, currencySymbol)}</span>
          </p>
          <p style={{ margin: '3px 0', display: 'flex', justifyContent: 'space-between' }}>
            <span style={{ marginRight: '15px', color: '#666' }}>Terendah:</span>
            <span style={{ fontWeight: '500' }}>{formatCurrency(data.Low, currencySymbol)}</span>
          </p>
          <p style={{ margin: '3px 0', display: 'flex', justifyContent: 'space-between' }}>
            <span style={{ marginRight: '15px', color: '#666' }}>Tutup:</span>
            <span style={{ fontWeight: 'bold', fontSize: '15px' }}>{formatCurrency(data.Close, currencySymbol)}</span>
          </p>
          {data.previousClose && (
            <p style={{ margin: '3px 0', display: 'flex', justifyContent: 'space-between' }}>
              <span style={{ marginRight: '15px', color: '#666' }}>Perubahan:</span>
              <span style={{ fontWeight: '500', color: isPositive ? '#4CAF50' : '#E53935' }}>
                {isPositive ? '+' : ''}{formatCurrency(priceChange, currencySymbol)} ({isPositive ? '+' : ''}{percentChange.toFixed(2)}%)
              </span>
            </p>
          )}
          <p style={{ margin: '3px 0', display: 'flex', justifyContent: 'space-between', borderTop: '1px solid #eee', paddingTop: '5px', marginTop: '5px' }}>
            <span style={{ marginRight: '15px', color: '#666' }}>Volume:</span>
            <span style={{ fontWeight: '500' }}>{data.Volume.toLocaleString('id-ID')}</span>
          </p>
        </div>
      </div>
    );
  }

  return null;
};

const StockChart = ({ data, currencySymbol = 'Rp' }) => {
  // Pastikan data tidak kosong
  if (!data || data.length === 0) {
    return (
      <div className="chart-container">
        <p>Tidak ada data yang tersedia untuk ditampilkan</p>
      </div>
    );
  }

  // Persiapkan data untuk chart (urutkan berdasarkan tanggal)
  const sortedData = [...data].sort((a, b) => {
    const dateA = new Date(a.Date || a.Datetime);
    const dateB = new Date(b.Date || b.Datetime);
    return dateA - dateB; // Ascending order for chart
  });
  
  // Tambahkan informasi previousClose untuk perhitungan perubahan
  const chartData = sortedData.map((item, index) => {
    if (index === 0) {
      return {
        ...item,
        previousClose: null,
        isPositive: true
      };
    }
    
    const previousClose = sortedData[index - 1].Close;
    const isPositive = item.Close >= previousClose;
    
    return {
      ...item,
      previousClose,
      isPositive
    };
  });

  // Fungsi untuk menentukan apakah menampilkan semua titik data
  const shouldShowAllTicks = chartData.length <= 30;

  // Format ticks pada sumbu X
  const formatXAxis = (tickItem) => {
    const date = new Date(tickItem);
    if (isNaN(date.getTime())) return tickItem;

    // Format singkat (DD/MM) jika banyak data
    if (chartData.length > 30) {
      return date.toLocaleDateString('id-ID', {
        day: '2-digit',
        month: '2-digit'
      });
    }

    // Format lengkap jika sedikit data
    return date.toLocaleDateString('id-ID', {
      day: '2-digit',
      month: '2-digit',
      year: '2-digit'
    });
  };

  // Cari nilai min dan max untuk sumbu Y
  const minValue = Math.min(...chartData.map(item => item.Low));
  const maxValue = Math.max(...chartData.map(item => item.High));

  // Tambahkan sedikit margin untuk visualisasi yang lebih baik
  const yAxisDomain = [
    minValue - (minValue * 0.01), // 1% lebih rendah dari minimum
    maxValue + (maxValue * 0.01)  // 1% lebih tinggi dari maksimum
  ];

  // Dapatkan data harga terakhir dan perubahan
  const firstPrice = chartData[0]?.Close || 0;
  const lastPrice = chartData[chartData.length - 1]?.Close || 0;
  const overallChange = lastPrice - firstPrice;
  const overallPercentChange = (overallChange / firstPrice) * 100;
  const isPositiveOverall = overallChange >= 0;

  // Mendapatkan tanggal terakhir
  const lastDate = chartData[chartData.length - 1]?.Date || '';

  return (
    <div className="chart-container">
      {/* Panel harga terakhir yang lebih menonjol */}
      <div style={{
        display: 'flex',
        justifyContent: 'space-between',
        alignItems: 'center',
        padding: '15px 20px',
        backgroundColor: 'white',
        borderRadius: '8px',
        boxShadow: '0 2px 8px rgba(0,0,0,0.1)',
        marginBottom: '20px',
        border: `1px solid ${isPositiveOverall ? 'rgba(76, 175, 80, 0.3)' : 'rgba(229, 57, 53, 0.3)'}`
      }}>
        <div>
          <div style={{ fontSize: '13px', color: '#666', marginBottom: '4px' }}>
            {formatDate(lastDate)} - Harga Terakhir
          </div>
          <div style={{ 
            fontSize: '24px', 
            fontWeight: 'bold', 
            color: isPositiveOverall ? '#4CAF50' : '#E53935'
          }}>
            {formatCurrency(lastPrice, currencySymbol)}
          </div>
        </div>
        <div style={{ textAlign: 'right' }}>
          <div style={{ fontSize: '13px', color: '#666', marginBottom: '4px' }}>
            Perubahan
          </div>
          <div style={{ 
            fontSize: '20px', 
            fontWeight: 'bold', 
            color: isPositiveOverall ? '#4CAF50' : '#E53935' 
          }}>
            {isPositiveOverall ? '+' : ''}{formatCurrency(overallChange, currencySymbol)} 
            <span style={{ fontSize: '16px' }}>
              ({isPositiveOverall ? '+' : ''}{overallPercentChange.toFixed(2)}%)
            </span>
          </div>
        </div>
      </div>

      <div className="chart-wrapper" style={{ 
        position: 'relative',
        backgroundColor: 'white',
        borderRadius: '8px',
        padding: '20px',
        boxShadow: '0 2px 8px rgba(0,0,0,0.1)'
      }}>
        <ResponsiveContainer width="100%" height={400}>
          <LineChart
            data={chartData}
            margin={{
              top: 20,
              right: 30,
              left: 20,
              bottom: 50
            }}
          >
            <CartesianGrid strokeDasharray="3 3" stroke="#e0e0e0" />
            <XAxis
              dataKey="Date"
              tickFormatter={formatXAxis}
              tick={{ fontSize: 12 }}
              interval={shouldShowAllTicks ? 0 : 'preserveStartEnd'}
              angle={-45}
              textAnchor="end"
              height={70}
            />
            <YAxis
              domain={yAxisDomain}
              tickFormatter={(value) => formatCurrency(value, currencySymbol)}
              tick={{ fontSize: 12 }}
              width={80}
            />
            <Tooltip content={<CustomTooltip currencySymbol={currencySymbol} />} />
            <Legend verticalAlign="top" height={36} />
            
            {/* Garis utama dengan warna berbeda berdasarkan segmen naik/turun */}
            {chartData.map((entry, index) => {
              // Skip entri pertama karena kita bandingkan dengan sebelumnya
              if (index === 0) return null;
              
              const prevEntry = chartData[index-1];
              const isUp = entry.Close >= prevEntry.Close;
              
              return (
                <Line
                  key={`segment-${index}`}
                  data={[prevEntry, entry]}
                  type="monotone"
                  dataKey="Close"
                  stroke={isUp ? '#4CAF50' : '#E53935'}
                  strokeWidth={2}
                  dot={false}
                  activeDot={false}
                  connectNulls
                  isAnimationActive={false}
                  legendType="none"
                />
              );
            })}
            
            {/* Dot yang berfungsi untuk menampilkan tooltip saja */}
            <Line
              type="monotone"
              dataKey="Close"
              name="Harga Penutupan"
              stroke="transparent"
              dot={(props) => {
                const { cx, cy, payload } = props;
                const isUp = payload.isPositive;
                return <circle cx={cx} cy={cy} r={2} fill={isUp ? '#4CAF50' : '#E53935'} />;
              }}
              activeDot={{ r: 5 }}
              strokeWidth={0}
            />
            
            <Brush
              dataKey="Date"
              height={30}
              stroke="#8884d8"
              tickFormatter={formatXAxis}
              startIndex={Math.max(0, chartData.length - Math.min(60, chartData.length))}
              fill="#ffffff"
            />
          </LineChart>
        </ResponsiveContainer>
      </div>
    </div>
  );
};

export default StockChart;
